+impl QeCollateral {
+    /// Verifies the QE Identity signature against the issuer certificate chain,
+    /// validates the chain up to the root CA, and enforces policy constraints on the QE Report.
+    pub fn verify(&self, root_ca_der: &[u8]) -> Result<()> {
+        // Parse issuer chain into individual DER certificates (concatenated)
+        let certs = parse_x509_chain(&self.qe_identity_issuer_chain)?;
+        if certs.is_empty() {
+            return Err(Error::InvalidCollateral("empty issuer chain".to_string()));
+        }
+
+        // Verify signature on qe_identity using leaf certificate's public key
+        let leaf_cert = &certs[0];
+        let leaf_pubkey = EcdsaPublicKey::from_x509_cert(leaf_cert)?;
+        verify_ecdsa_signature(&self.qe_identity, &self.qe_identity_signature, &leaf_pubkey)?;
+
+        // Verify certificate chain up to root CA
+        verify_x509_chain(&certs, root_ca_der)?;
+
+        // Parse and enforce policy on QE Report
+        let qe_report = parse_qe_report(&self.qe_identity)?;
+        Self::enforce_policy(&qe_report)?;
+
+        Ok(())
+    }
+
+    fn enforce_policy(report: &QeReport) -> Result<()> {
+        // Enforce version constraint
+        if report.version != 1 {
+            return Err(Error::InvalidCollateral("unsupported QE report version".to_string()));
+        }
+        // TODO: Add additional policy checks (e.g., FMPSC, TCB levels) based on DCAP spec
+        // e.g., if report.fmspc != EXPECTED_INTEL_FMPSC { ... }
+        Ok(())
+    }
